|champion     = Vel'Koz
|skill        = W
|icon         = Void Rift.png
|blurb        = {{sbc|Active:}} {{ci|Vel'Koz}} cracks a rift in the target direction that opens after a brief delay, cascading through the area to deal {{as|magic damage}} to enemies within.
|blurb2       = After a brief delay, the rift collapses, dealing {{as|magic damage}} to enemies within.
|blurb3       = '''Vel'Koz''' periodically stocks a charge of ''Void Rift'', up to a maximum of 2.
|description  = {{sbc|Active:}} '''Vel'Koz''' cracks a rift in the target direction that opens after a {{fd|0.25}}-second delay, cascading through the area over {{fd|0.65}} seconds to deal {{as|magic damage}} to enemies within.
|leveling     = {{st|Magic Damage|{{ap|30 to 110}} {{as|(+ 20% AP)}}}} 
|description2 = After {{tt|{{fd|0.75}} seconds|Estimated}}, the rift violently collapses, dealing {{as|magic damage}} to enemies within and granting {{tip|sight}} of the surrounding area for {{fd|0.25}} seconds.
|leveling2    = {{st|Magic Damage|{{ap|45 to 165}} {{as|(+ 25% AP)}}|Total Magic Damage|{{ap|30+45 to 110+165}} {{as|(+ 45% AP)}}}}
|description3 = '''Vel'Koz''' periodically [[stock]]s a ''Void Rift'' charge, up to a maximum of 2.
|cost         = {{ap|50 to 70}}
|costtype     = Mana + 1 Charge
|static       = {{fd|1.5}}
|recharge     = {{ap|19 to 15}}
|range        = {{dv|{{tip|cr|icononly = true}} {{tt|1105|Ripple missile range}}|{{tip|er|icononly = true}} {{tt|1105|Rift collapse distance}}|{{tt|-95|Rift collapsing backwards distance}}}}
|width        = {{dv|{{tip|er|icononly = true}} {{tt|175|Ripple missile width}}|{{tt|175|Rift collapse width}}}}
|speed        = {{tt|1700|Ripple missile speed}}
|cast time    = none
